diff --git a/test/suites/api/test_copy.c b/test/suites/api/test_copy.c
index 656d98d..a6032af 100644
--- a/test/suites/api/test_copy.c
+++ b/test/suites/api/test_copy.c
@@ -364,6 +364,25 @@ static void test_deep_copy_circular_references(void) {
     json_decref(json);
 }

+static void test_deep_copy_max_depth(void) {
+    json_t *json;
+    json_t *copy;
+    int i;
+
+    json = json_array();
+    for (i = 1; i < JSON_PARSER_MAX_DEPTH + 100; i++) {
+        json_t *outer = json_array();
+        json_array_append_new(outer, json);
+        json = outer;
+    }
+
+    copy = json_deep_copy(json);
+    if (copy)
+        fail("json_deep_copy didn't fail for a too deeply nested structure!");
+
+    json_decref(json);
+}
+
 static void run_tests() {
     test_copy_simple();
     test_deep_copy_simple();
@@ -372,4 +391,5 @@ static void run_tests() {
     test_copy_object();
     test_deep_copy_object();
     test_deep_copy_circular_references();
+    test_deep_copy_max_depth();
 }
diff --git a/test/suites/api/test_dump.c b/test/suites/api/test_dump.c
index e8cb519..a4fbaa3 100644
--- a/test/suites/api/test_dump.c
+++ b/test/suites/api/test_dump.c
@@ -297,6 +297,39 @@ static void embed() {
     }
 }

+static json_t *build_nested_array(int depth) {
+    json_t *json = json_array();
+    int i;
+
+    for (i = 1; i < depth; i++) {
+        json_t *outer = json_array();
+        json_array_append_new(outer, json);
+        json = outer;
+    }
+
+    return json;
+}
+
+static void max_depth() {
+    json_t *json;
+    char *result;
+
+    /* A structure nested exactly to the limit must still serialize. */
+    json = build_nested_array(JSON_PARSER_MAX_DEPTH);
+    result = json_dumps(json, 0);
+    if (!result)
+        fail("json_dumps failed for a structure within the depth limit");
+    free(result);
+    json_decref(json);
+
+    /* A structure nested deeper than the limit must fail cleanly rather
+       than overflow the stack. */
+    json = build_nested_array(JSON_PARSER_MAX_DEPTH + 100);
+    if (json_dumps(json, 0) != NULL)
+        fail("json_dumps didn't fail for a too deeply nested structure");
+    json_decref(json);
+}
+
 static void run_tests() {
     encode_null();
     encode_twice();
@@ -308,4 +341,5 @@ static void run_tests() {
     dumpb();
     dumpfd();
     embed();
+    max_depth();
 }
